import { useState } from "react";
import { Modal } from "./Modal.jsx";

export default function App() {
  const [abierto, setAbierto] = useState(false);
  const cerrar = () => setAbierto(false);

  return (
    <main style={{ maxWidth: 520, margin: "2rem auto", fontFamily: "system-ui, sans-serif" }}>
      <h1>Mis pedidos</h1>
      <p>Pedido #1024: 2 pizzas familiares, S/ 79.80</p>
      <button onClick={() => setAbierto(true)}>Ver detalle</button>

      <Modal abierto={abierto} titulo="Detalle del pedido #1024" onCerrar={cerrar}>
        <ul>
          <li>Pizza Americana familiar: S/ 39.90</li>
          <li>Pizza Hawaiana familiar: S/ 39.90</li>
        </ul>
        <p>Entrega en Miraflores, hoy entre 7 y 8 p. m.</p>
      </Modal>
    </main>
  );
}
